/* @autogenerated */
package net.civeira.phylax.feature.observe.issue;

import java.util.List;
import java.util.Map;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.feature.observe.store.ObsLog;

class IssueFingerprintUnitTest {

  private static final List<String> IN_APP = List.of("com.acme.");

  private static String javaStack(final int line, final String message) {
    return "java.lang.IllegalStateException: " + message + "\n"
        + "\tat java.base/java.util.Optional.orElseThrow(Optional.java:403)\n"
        + "\tat com.acme.orders.OrderService.find(OrderService.java:" + line + ")\n"
        + "\tat com.acme.orders.OrderController.get(OrderController.java:" + (line + 7) + ")\n"
        + "\tat io.vertx.core.impl.ContextImpl.run(ContextImpl.java:12)";
  }

  private static ErrorEvent event(final String stack, final String message) {
    return new ErrorEvent("api", 1L, "ERROR", null, message, stack, null, null, null, null);
  }

  @Test
  @DisplayName("Same cause and place: same fingerprint, whatever the line numbers and the data")
  void stableFingerprint() {
    IssueFingerprint.Result a =
        IssueFingerprint.of(event(javaStack(40, "order 1234 not found"), null), IN_APP);
    IssueFingerprint.Result b =
        IssueFingerprint.of(event(javaStack(52, "order 98 not found"), null), IN_APP);
    Assertions.assertEquals(a.fingerprint(), b.fingerprint());
    Assertions.assertEquals("java.lang.IllegalStateException",
        IssueFingerprint.type(event(javaStack(1, "x"), null)));
    Assertions.assertEquals("com.acme.orders.OrderService.find", a.culprit());
    Assertions.assertEquals("java.lang.IllegalStateException: order ? not found",
        IssueFingerprint.of(event(javaStack(1, "x"), "order 1234 not found"), IN_APP).title());
  }

  @Test
  @DisplayName("Only the in-app frames count; another place is another issue")
  void inAppFrames() {
    Assertions.assertEquals(
        List.of("com.acme.orders.OrderService.find", "com.acme.orders.OrderController.get"),
        IssueFingerprint.frames(javaStack(1, "x"), IN_APP));
    String other = javaStack(1, "x").replace("OrderService.find", "OrderService.save");
    Assertions.assertNotEquals(
        IssueFingerprint.of(event(javaStack(1, "x"), null), IN_APP).fingerprint(),
        IssueFingerprint.of(event(other, null), IN_APP).fingerprint());
  }

  @Test
  @DisplayName("Browser stacks: function or file without hash, the libraries left out")
  void browserStacks() {
    String chrome = "TypeError: Cannot read properties of undefined (reading 'id')\n"
        + "    at OrderComponent.load (https://app.local/main.4f2a9c01d3e5.js:1:2345)\n"
        + "    at https://app.local/chunk-ab12cd34ef56.js:3:9\n"
        + "    at ZoneDelegate.invoke (https://app.local/polyfills.js:1:99)";
    Assertions.assertEquals(List.of("OrderComponent.load", "chunk.js"),
        IssueFingerprint.frames(chrome, IN_APP));
    Assertions.assertEquals("TypeError", IssueFingerprint.type(event(chrome, null)));
    String firefox =
        "load@https://app.local/main.4f2a9c01d3e5.js:1:2345\n@https://app.local/main.js:2:1";
    Assertions.assertEquals(List.of("load", "main.js"), IssueFingerprint.frames(firefox, IN_APP));
  }

  @Test
  @DisplayName("Without stack the normalized message decides; a forced fingerprint wins")
  void withoutStack() {
    ErrorEvent a = new ErrorEvent("api", 1L, "ERROR", "Timeout", "call 42 to 10.0.0.1 failed", null,
        null, null, null, null);
    ErrorEvent b = new ErrorEvent("api", 1L, "ERROR", "Timeout", "call 7 to 10.0.0.9 failed", null,
        null, null, null, null);
    Assertions.assertEquals(IssueFingerprint.of(a, IN_APP).fingerprint(),
        IssueFingerprint.of(b, IN_APP).fingerprint());
    ErrorEvent forced =
        new ErrorEvent("api", 1L, "ERROR", "Timeout", "x", null, null, "payments-down", null, null);
    Assertions.assertEquals("payments-down", IssueFingerprint.of(forced, IN_APP).fingerprint());
  }

  @Test
  @DisplayName("Error logs with an exception are events; the rest and the own logs are not")
  void events() {
    ObsLog own = new ObsLog(1L, "api", "ERROR", "com.acme.Svc", "boom", null, null,
        javaStack(1, "x"), Map.of(), null, null);
    Assertions.assertTrue(ErrorEvents.from(own, "com.acme.feature.observe").isPresent());
    ObsLog plain = new ObsLog(1L, "api", "ERROR", "com.acme.Svc", "no exception", null, null, null,
        Map.of(), null, null);
    Assertions.assertTrue(ErrorEvents.from(plain, "com.acme.feature.observe").isEmpty());
    ObsLog info = new ObsLog(1L, "api", "INFO", "com.acme.Svc", "boom", null, null,
        javaStack(1, "x"), Map.of(), null, null);
    Assertions.assertTrue(ErrorEvents.from(info, "com.acme.feature.observe").isEmpty());
    ObsLog loop = new ObsLog(1L, "api", "ERROR", "com.acme.feature.observe.issue.IssueAggregator",
        "x", null, null, javaStack(1, "x"), Map.of(), null, null);
    Assertions.assertTrue(ErrorEvents.from(loop, "com.acme.feature.observe").isEmpty());
    ObsLog front = new ObsLog(1L, "ui", "ERROR", "default", "Unhandled error", "t1", null, null,
        Map.of("log.args",
            "[{\"name\":\"TypeError\",\"message\":\"x is undefined\",\"stack\":\"TypeError: x is undefined\\n    at load (https://app/main.js:1:2)\"}]"),
        null, null);
    ErrorEvent event = ErrorEvents.from(front, "com.acme.feature.observe").orElseThrow();
    Assertions.assertEquals("TypeError", event.type());
    Assertions.assertEquals("x is undefined", event.message());
    Assertions.assertEquals("t1", event.traceId());
  }
}
